import{START,localDate,dayOf,addDays,initial,schedule,day,ensure,totals,level,streak,editSchedule}from'./model.mjs';
const $=s=>document.querySelector(s),KEY='foco-final-v1',API='https://aqfyifldtmbusmlxfjaf.supabase.co/functions/v1/foco-notifications';const setup=new URLSearchParams(location.hash.slice(1));if(setup.has('setup')){localStorage.setItem('foco-install-key',setup.get('setup'));history.replaceState(null,'',location.pathname+'#agenda')}const INSTALL_KEY=localStorage.getItem('foco-install-key')||'';let state,storageOK=true;try{state=JSON.parse(localStorage.getItem(KEY)||'null')||initial();if(state.version!==1)throw Error('Versão desconhecida')}catch(e){storageOK=false;state=initial();}let selected=localDate(),month=selected.slice(0,7),view='agenda';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const mins=m=>m>=60?Math.floor(m/60)+'h '+(m%60?m%60+'min':''):m+'min';const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});const nav=[['agenda','◷','Agenda'],['calendar','▦','Calendário'],['progress','↗','Progresso'],['courses','▤','Cursos'],['settings','⚙','Ajustes']];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#saveStatus').textContent='✓ Salvo neste aparelho';return true}catch(e){storageOK=false;$('#saveStatus').textContent='Falha ao salvar';toast('Não foi possível salvar. Exporte uma cópia antes de fechar.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
const deviceId=()=>{if(!state.settings)state.settings={};if(!state.settings.deviceId)state.settings.deviceId=crypto.randomUUID();return state.settings.deviceId};
const latestTasks=()=>state.revisions.slice().sort((a,b)=>b.from.localeCompare(a.from))[0].tasks;
const remoteSchedules=()=>latestTasks().map(t=>({task_id:t.id,title:t.title,time:t.time,weekdays:t.days,reminder_enabled:!!t.remind,second_reminder_minutes:Number(t.second)||0}));
async function api(action,payload={}){if(!INSTALL_KEY)throw Error('Abra o link de instalação fornecido para configurar este aparelho.');let r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-Install-Key':INSTALL_KEY},body:JSON.stringify({action,device_id:deviceId(),...payload})});let data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Falha na comunicação');return data}
function queue(action,payload){state.pending=Array.isArray(state.pending)?state.pending:[];if(action==='sync')state.pending=state.pending.filter(x=>x.action!=='sync');if(action==='complete')state.pending=state.pending.filter(x=>!(x.action==='complete'&&x.payload.task_id===payload.task_id&&x.payload.local_date===payload.local_date));state.pending.push({action,payload});save()}
async function sendOrQueue(action,payload){if(!state.settings?.notifications)return;try{await api(action,payload)}catch{queue(action,payload)}}
async function flushPending(){if(!state.settings?.notifications||!navigator.onLine||!state.pending?.length)return;let rest=[];for(let item of state.pending){try{await api(item.action,item.payload)}catch{rest.push(item)}}state.pending=rest;save()}
function keyBytes(value){let pad='='.repeat((4-value.length%4)%4),base=(value+pad).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
async function enableNotifications(){let standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone;if(!standalone)throw Error('No iPhone, adicione primeiro à Tela de Início e abra pelo ícone.');if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('Este aparelho não oferece notificações web.');let permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Permissão negada. Ative em Ajustes → Notificações → Foco Até o Final.');let reg=await navigator.serviceWorker.ready,conf=await api('config');let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(conf.vapid_public)});await api('subscribe',{subscription:sub.toJSON(),schedules:remoteSchedules()});state.settings.notifications=true;state.settings.notificationStatus='Ativadas';let d=day(state,localDate());for(let [task_id,e] of Object.entries(d.entries))if(e.done)await api('complete',{task_id,local_date:localDate(),done:true});save();toast('Notificações ativadas. Faça agora o teste.');render()}
async function disableNotifications(){try{await api('unsubscribe')}catch{}state.settings.notifications=false;state.settings.notificationStatus='Desativadas';state.pending=[];save();render();toast('Notificações desativadas.')}
async function syncNotifications(){if(!state.settings?.notifications)return;await sendOrQueue('sync',{schedules:remoteSchedules()})}
async function testNotification(){if(!state.settings?.notifications)throw Error('Ative as notificações primeiro.');await api('test');toast('Notificação de teste enviada. Verifique o iPhone.')}

function go(v){location.hash=v;view=v;render()}window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'agenda';render()});
function button(action,label,cls='',attrs=''){return '<button type="button" class="btn '+cls+'" data-action="'+action+'" '+attrs+'>'+label+'</button>'}
function render(){if(!nav.some(n=>n[0]===view))view='agenda';$('#navigation').innerHTML=nav.map(([v,i,l])=>'<a href="#'+v+'" class="'+(view===v?'active':'')+'" '+(view===v?'aria-current="page"':'')+'><b aria-hidden="true">'+i+'</b>'+l+'</a>').join('');$('#app').innerHTML=({agenda,calendar,progress,courses,settings}[view])();if(!storageOK)$('#saveStatus').textContent='Armazenamento indisponível — exporte seus dados';}
function taskRows(d){return d.tasks.map(t=>{let e=d.entries[t.id]||{};let time=e.completedAt?new Date(e.completedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}):'';return '<div class="task '+(e.done?'done':'')+'"><time>'+esc(t.time)+'</time><input class="check" type="checkbox" aria-label="Concluir '+esc(t.title)+'" data-check="'+esc(t.id)+'" '+(e.done?'checked':'')+' '+(selected>localDate()?'disabled':'')+'><div><div class="task-name">'+esc(t.title)+'</div><small>'+ (e.done?'Concluído às '+time+' · ':'')+(e.minutes?mins(e.minutes):t.kind==='main'?'Seu compromisso principal':t.remind?'Lembrete configurado · envio pendente':'Rotina pessoal')+'</small></div><button data-action="minutes" data-id="'+esc(t.id)+'" aria-label="Registrar tempo de '+esc(t.title)+'" '+(selected>localDate()?'disabled':'')+'>'+(e.minutes?mins(e.minutes):'+ tempo')+'</button></div>'}).join('')}
function agenda(){let d=day(state,selected),t=totals(d),l=level(d),isToday=selected===localDate();let now=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'}).format(new Date());let remaining=d.tasks.filter(x=>!d.entries[x.id]?.done);let focus=(isToday?remaining.filter(x=>x.time<=now).at(-1):null)||remaining[0];let seq=streak(state,localDate());return '<div class="heading"><div><h1>'+ (isToday?'Seu dia, com intenção.':'Sua agenda')+'</h1><p class="subtitle" style="margin-bottom:0">'+esc(dateLabel(selected))+'</p></div><div class="date-control">'+button('prev','‹','', 'aria-label="Dia anterior"')+'<input type="date" id="date" aria-label="Data da agenda" value="'+selected+'" min="'+START+'">'+button('next','›','','aria-label="Próximo dia"')+'</div></div><section class="hero"><div><span class="eyebrow">'+(isToday?'SEU PRÓXIMO PASSO':'UM PASSO DE CADA VEZ')+'</span><h2>'+esc(focus?focus.title:'Agenda concluída!')+'</h2><p>'+ (focus?esc(focus.time)+' · Reserve um momento para o que importa.':'Você cumpriu a programação deste dia.')+'</p>'+ (focus?button('focus','Registrar meu avanço →','','data-id="'+esc(focus.id)+'" '+(selected>localDate()?'disabled':'')):'')+'</div><div class="hero-orbit" aria-hidden="true">'+(focus?'↗':'✓')+'</div></section><div class="stats"><div class="stat"><span class="label">Agenda concluída</span><strong>'+t.percent+'<small>%</small></strong><small>'+t.done+' de '+t.total+' atividades</small></div><div class="stat"><span class="label">Tempo de estudo</span><strong>'+mins(t.study)+'</strong><small>Tempo registrado</small></div><div class="stat"><span class="label">Sua sequência</span><strong>'+seq.current+' <small>dias</small></strong><small>Um pouco, todos os dias</small></div></div><div class="columns"><section class="panel"><div class="panel-head"><h2>Agenda do dia</h2><span class="pill">'+ (isToday?'HOJE':'HISTÓRICO / AGENDA')+'</span></div>'+taskRows(d)+'</section><div class="right-col"><section class="panel"><span class="eyebrow">CONSTÂNCIA ANTES DA PERFEIÇÃO</span><h2 style="margin-top:14px">'+l.name+'</h2><div class="progress"><div style="width:'+Math.min(100,t.sql/30*100)+'%"></div></div><p class="quiet">'+Math.min(30,t.sql)+' de 30 minutos de SQL para cumprir o dia mínimo.</p><div class="rule"><strong>🔴 Dia mínimo</strong>30 minutos de SQL.</div><div class="rule"><strong>🟡 Dia normal</strong>SQL, bloco técnico, leitura e academia quando programada.</div><div class="rule"><strong>🟢 Dia excelente</strong>Tudo do dia normal + projeto prático.</div><p class="quiet">No domingo, o bloco técnico não é obrigatório.</p></section><section class="panel"><span class="eyebrow">FECHAR O DIA</span><p class="quote">Pequenos avanços.<br>Grandes conclusões.</p>'+button('closing','Registrar meu dia →','primary')+(d.closing?.advance?'<p class="quiet">'+esc(d.closing.advance)+'</p>':'')+'</section></div></div><div class="callout">Os lembretes automáticos ainda precisam ser conectados ao serviço de envio. <a href="#settings">Ver notificações →</a></div>'}
function calendar(){let first=month+'-01',n=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();let cells=['D','S','T','Q','Q','S','S'].map(x=>'<div class="weekday">'+x+'</div>').join('')+'<div style="grid-column:span '+dayOf(first)+';display:'+(dayOf(first)?'block':'none')+'"></div>';for(let i=1;i<=n;i++){let date=month+'-'+String(i).padStart(2,'0'),d=day(state,date),l=level(d),past=date<localDate();let status=date<state.started||date>localDate()?'—':l.rank?'✅':totals(d).done||totals(d).study?'🟡':past?'❌':'·';cells+='<button data-action="open-day" data-date="'+date+'" class="'+(date===localDate()?'today':'')+'" '+(date<START?'disabled':'')+' aria-label="'+date+' '+(status==='—'?'Sem registro':l.name)+'">'+i+'<span>'+status+'</span></button>'}return '<h1>Um dia de cada vez.</h1><p class="subtitle">Sua constância ganha forma ao longo do mês.</p><section class="panel"><div class="panel-head"><h2>Calendário</h2><input type="month" id="month" aria-label="Mês do calendário" value="'+month+'" min="2026-10" style="width:auto"></div><div class="calendar">'+cells+'</div><p class="quiet">✅ Pelo menos 30 min de SQL · 🟡 Parcial · ❌ Sem atividade registrada · — Sem acompanhamento / futuro</p><p class="quiet">Toque em uma data para consultar ou completar o histórico.</p></section>'}
function progress(){let dates=Object.keys(state.days).filter(d=>d<=localDate()),sum={study:0,read:0,gym:0,project:0,sql:0,done:0,total:0},studied=0,sqlDays=0;for(let date of dates){let t=totals(state.days[date]);Object.keys(sum).forEach(k=>sum[k]+=t[k]);if(t.study>0)studied++;if(t.sql>0)sqlDays++}let seq=streak(state,localDate());let week=[];for(let i=6;i>=0;i--){let date=addDays(localDate(),-i);week.push({date,t:totals(day(state,date))})}let max=Math.max(60,...week.map(x=>x.t.study));let months=[...new Set(dates.map(d=>d.slice(0,7)))].sort().reverse();return '<h1>Você está avançando.</h1><p class="subtitle">Cada minuto registrado faz parte da sua história.</p><div class="stats"><div class="stat"><span class="label">Dias estudados</span><strong>'+studied+'</strong><small>Com tempo de estudo registrado</small></div><div class="stat"><span class="label">Horas de estudo</span><strong>'+(sum.study/60).toFixed(1)+'</strong><small>SQL + complementares + projeto</small></div><div class="stat"><span class="label">Melhor sequência</span><strong>'+seq.best+'</strong><small>Atual: '+seq.current+' dias</small></div></div><div class="columns"><section class="panel"><h2>Seus últimos 7 dias</h2><div class="bars">'+week.map(x=>'<div class="bar-wrap"><div>'+x.t.study+'m</div><div class="bar" style="height:'+Math.round(x.t.study/max*100)+'px"></div>'+new Date(x.date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'})+'</div>').join('')+'</div><p class="quiet">Minutos estudados por dia.</p></section><section class="panel"><h2>Além dos números</h2>'+[['Dias com SQL',sqlDays],['Horas de leitura',(sum.read/60).toFixed(1)],['Treinos concluídos',sum.gym],['Dias com projeto',dates.filter(d=>totals(state.days[d]).project>0).length]].map(([a,b])=>'<div class="list-row"><span>'+a+'</span><strong>'+b+'</strong></div>').join('')+'</section></div><section class="panel"><h2>Evolução mensal</h2>'+ (months.length?months.map(m=>{let ds=dates.filter(d=>d.startsWith(m)),ts=ds.map(d=>totals(state.days[d]));let done=ts.reduce((a,t)=>a+t.done,0),total=ts.reduce((a,t)=>a+t.total,0);return '<div class="list-row"><div><strong>'+new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})+'</strong><p class="quiet">SQL: '+ts.filter(t=>t.sql>0).length+' dias · Academia: '+ts.reduce((a,t)=>a+t.gym,0)+' · Leitura: '+ts.filter(t=>t.read>0).length+' dias · Projeto: '+ts.filter(t=>t.project>0).length+' dias</p></div><strong>'+(total?Math.round(done/total*100):0)+'%</strong></div>'}).join(''):'<p class="empty">Seu primeiro registro começa esta história.</p>')+'<p class="quiet">O percentual considera as agendas registradas, sem incluir dias futuros.</p></section>'}
function courseHours(name){return Object.values(state.days).reduce((a,d)=>a+d.tasks.filter(t=>t.course===name).reduce((b,t)=>b+(d.entries[t.id]?.minutes||0),0),0)}
function courses(){return '<h1>Menos começos. Mais conclusões.</h1><p class="subtitle">Um curso principal. Conteúdos complementares no seu ritmo.</p><div class="course-grid">'+state.courses.map((c,i)=>'<section class="panel '+(c.principal?'course-main':'')+'"><div class="panel-head"><span class="course-icon">'+['SQL','Py','BI','PA'][i]+'</span><span class="pill">'+(c.principal?'CURSO PRINCIPAL':'COMPLEMENTAR')+'</span></div><h2>'+c.name+'</h2><p class="quiet">'+c.status+'</p><div class="progress"><div style="width:'+c.percent+'%"></div></div><div class="list-row"><strong>'+c.percent+'% concluído</strong><span>'+mins(courseHours(c.name))+'</span></div><p class="quiet">Início: '+(c.start||'Ainda não registrado')+'<br>Conclusão: '+(c.end||'Um passo de cada vez')+'</p>'+button('course','Atualizar progresso','', 'data-id="'+i+'"')+(!c.principal&&state.courses.find(x=>x.principal)?.percent===100?' '+button('principal','Tornar principal','ghost','data-id="'+i+'"'):'')+'</section>').join('')+'</div>'}
function settings(){let tasks=latestTasks();let standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone;let active=!!state.settings?.notifications;let permission='Notification'in window?({granted:'Permitida',denied:'Negada',default:'Não solicitada'}[Notification.permission]):'Indisponível aqui';return '<h1>Do seu jeito.</h1><p class="subtitle">Ajuste sua rotina sem perder o que já conquistou.</p><section class="panel"><div class="panel-head"><h2>Notificações</h2><span class="pill">'+(active?'ATIVADAS':'DESATIVADAS')+'</span></div><p class="quiet">'+(active?'Os lembretes são enviados pela internet mesmo com o aplicativo fechado.':'Ative os lembretes depois de instalar o aplicativo na tela inicial do iPhone.')+'</p><div class="list-row"><span>Instalado na tela inicial</span><strong>'+(standalone?'Sim':'Ainda não')+'</strong></div><div class="list-row"><span>Permissão do iPhone</span><strong>'+permission+'</strong></div><div class="list-row"><span>Atividades com lembrete</span><strong>'+tasks.filter(t=>t.remind).length+'</strong></div><div class="actions" style="justify-content:flex-start">'+(active?button('disable-notifications','Desativar notificações','ghost')+button('test','Testar notificação','primary'):button('enable-notifications','Ativar notificações','primary'))+'</div><p class="quiet">No iPhone: Safari → Compartilhar → Adicionar à Tela de Início. Abra pelo novo ícone e toque em “Ativar notificações”. Se negar a permissão, habilite em Ajustes → Notificações → Foco Até o Final.</p></section><section class="panel"><div class="panel-head"><h2>Programação semanal</h2><span class="pill">HORÁRIO DE BRASÍLIA</span></div><p class="quiet">Alterações valem de hoje em diante e atualizam automaticamente os próximos lembretes. Os dias anteriores são preservados.</p>'+tasks.map(t=>'<div class="list-row"><div><strong>'+esc(t.time)+' · '+esc(t.title)+'</strong><div class="quiet">'+t.days.map(d=>['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][d]).join(', ')+' · '+(t.remind?'Lembrete: sim'+(t.second?' + um aviso após '+t.second+' min':''):'Sem lembrete')+'</div></div>'+button('edit','Editar','','data-id="'+esc(t.id)+'"')+'</div>').join('')+'</section><section class="panel"><h2>Seus dados</h2><p class="quiet">Os registros ficam neste aparelho. Limpar os dados do Safari pode apagar o histórico. Exporte uma cópia regularmente.</p>'+button('export','Exportar cópia')+' '+button('import','Importar cópia','ghost')+'<input type="file" accept="application/json,.json" id="importFile" hidden></section>'}
function openDialog(content){$('#dialog').innerHTML=content;$('#dialog').showModal()}
function minutes(id,complete=false){let d=day(state,selected),t=d.tasks.find(x=>x.id===id);if(!t)return;let e=d.entries[id]||{};openDialog('<h2>'+esc(t.title)+'</h2><p class="quiet">Registre apenas o tempo que você realmente dedicou à atividade.</p><form id="timeForm"><label>Minutos realizados<input name="minutes" type="number" min="0" max="1440" step="1" required value="'+(e.minutes||0)+'"></label><label style="margin-top:16px"><input name="done" type="checkbox" '+(complete||e.done?'checked':'')+'> Marcar atividade como concluída</label><div class="actions">'+button('cancel','Cancelar')+'<button class="btn primary">Salvar</button></div></form>');$('#timeForm').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),m=Number(f.get('minutes'));if(!Number.isInteger(m)||m<0||m>1440)return;let dst=ensure(state,selected),done=f.has('done');dst.entries[id]={minutes:m,done,completedAt:done?(e.completedAt||new Date().toISOString()):null};if(t.course&&m){let c=state.courses.find(x=>x.name===t.course);if(c){c.start=c.start&&c.start<selected?c.start:selected;if(c.percent<100)c.status='Em andamento'}}save();$('#dialog').close();render()}}
function closing(){let d=day(state,selected),t=totals(d),c=d.closing||{};openDialog('<h2>Como foi seu dia?</h2><p class="quiet">Estudo: '+mins(t.study)+' · Produtivo: '+mins(t.productive)+' · Lazer: '+mins(t.leisure)+' (calculados dos tempos registrados)</p><form id="closeForm"><div class="form-grid"><label class="full">Principal avanço<textarea name="advance" maxlength="1200">'+esc(c.advance||'')+'</textarea></label><label>Nota do dia (0 a 10)<input name="rating" type="number" min="0" max="10" step="1" required value="'+(c.rating??'')+'"></label><label>Avançou no objetivo?<select name="advanced"><option value="yes" '+(c.advanced==='yes'?'selected':'')+'>Sim</option><option value="no" '+(c.advanced==='no'?'selected':'')+'>Não</option></select></label></div><div class="actions">'+button('cancel','Cancelar')+'<button class="btn primary">Salvar fechamento</button></div></form>');$('#closeForm').onsubmit=e=>{e.preventDefault();ensure(state,selected).closing=Object.fromEntries(new FormData(e.target));save();$('#dialog').close();render();toast('Fechamento salvo: '+level(day(state,selected)).name)}}
function edit(id){let tasks=structuredClone(state.revisions.slice().sort((a,b)=>b.from.localeCompare(a.from))[0].tasks),t=tasks.find(x=>x.id===id);openDialog('<h2>Editar atividade</h2><form id="editForm"><div class="form-grid"><label class="full">Atividade<input name="title" required maxlength="100" value="'+esc(t.title)+'"></label><label>Horário<input type="time" name="time" required value="'+t.time+'"></label><label>Curso relacionado<select name="course"><option value="">Nenhum / automático</option>'+state.courses.map(c=>'<option '+(c.name===t.course?'selected':'')+'>'+c.name+'</option>').join('')+'</select></label><label>Notificação<select name="remind"><option value="yes" '+(t.remind?'selected':'')+'>Sim</option><option value="no" '+(!t.remind?'selected':'')+'>Não</option></select></label><label>Segundo lembrete (min)<input name="second" type="number" min="0" max="180" step="1" value="'+t.second+'"></label><div class="full"><label>Dias da semana (repetir semanalmente)</label><div class="days">'+['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((x,i)=>'<label><input type="checkbox" name="days" value="'+i+'" '+(t.days.includes(i)?'checked':'')+'> '+x+'</label>').join('')+'</div></div></div><p class="quiet">Segundo lembrete: 0 desativa. Máximo de um aviso adicional por atividade.</p><div class="actions">'+button('cancel','Cancelar')+'<button class="btn primary">Salvar agenda</button></div></form>');$('#editForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),days=f.getAll('days').map(Number);if(!days.length){toast('Selecione pelo menos um dia.');return}let title=String(f.get('title')).trim();if(!title)return;t.customTitle=t.customTitle||title!==t.title||String(f.get('course'))!==t.course;t.title=title;t.time=f.get('time');t.course=f.get('course');t.days=days;t.remind=f.get('remind')==='yes';t.second=Number(f.get('second'));editSchedule(state,tasks,localDate());save();syncNotifications();$('#dialog').close();render();toast('Agenda e próximos lembretes atualizados.')}}
function course(i){let c=state.courses[i];openDialog('<h2>'+c.name+'</h2><form id="courseForm"><label>Percentual concluído<input type="number" name="percent" min="0" max="100" required step="1" value="'+c.percent+'"></label><label>Data de início<input name="start" type="date" max="'+localDate()+'" value="'+c.start+'"></label><div class="actions">'+button('cancel','Cancelar')+'<button class="btn primary">Salvar progresso</button></div></form>');$('#courseForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),before=c.percent;c.percent=Number(f.get('percent'));c.start=f.get('start')||(c.percent?localDate():'');c.status=c.percent===100?'Concluído':c.percent||c.start?'Em andamento':'Não iniciado';c.end=c.percent===100?(c.end||localDate()):'';save();$('#dialog').close();render();if(c.percent===100&&before!==100)openDialog('<div style="text-align:center;padding:25px 5px"><span style="font-size:45px">✓</span><h2>'+c.name.toUpperCase()+' CONCLUÍDO</h2><p>Mais importante do que começar é terminar.</p><p class="quiet">Conclusão registrada em '+c.end+'.</p>'+button('cancel','Guardar essa conquista','primary')+'</div>')}}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='foco-ate-o-final-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action,id=el.dataset.id;if(a==='prev'||a==='next'){selected=addDays(selected,a==='prev'?-1:1);if(selected<START)selected=START;render()}if(a==='open-day'){selected=el.dataset.date;go('agenda')}if(a==='focus')minutes(id,true);if(a==='minutes')minutes(id);if(a==='closing'){if(selected>localDate())return toast('O fechamento fica disponível no dia da atividade.');closing()}if(a==='cancel')$('#dialog').close();if(a==='edit')edit(id);if(a==='course')course(Number(id));if(a==='principal'){let c=state.courses[Number(id)];if(c.percent===100)return toast('Escolha um curso ainda não concluído.');if(state.courses.find(x=>x.principal)?.percent!==100)return;state.courses.forEach(x=>x.principal=x===c);let tasks=structuredClone(state.revisions.slice().sort((a,b)=>b.from.localeCompare(a.from))[0].tasks);let main=tasks.find(t=>t.kind==='main');if(main){main.course=c.name;main.title='Curso principal — '+c.name;main.customTitle=true}editSchedule(state,tasks,localDate());save();render();toast('Curso principal atualizado. A regra mínima continua sendo 30 min de SQL até ser revisada.')}if(a==='enable-notifications')enableNotifications().catch(e=>toast(e.message));if(a==='disable-notifications')disableNotifications();if(a==='test')testNotification().catch(e=>toast(e.message));if(a==='export')exportData();if(a==='import')$('#importFile').click()});
document.addEventListener('change',e=>{let el=e.target;if(el.id==='date'){if(el.value>=START){selected=el.value;render()}}if(el.id==='month'){month=el.value;render()}if(el.dataset.check){let id=el.dataset.check,d=ensure(state,selected),entry=d.entries[id]||{minutes:0};entry.done=el.checked;entry.completedAt=entry.done?new Date().toISOString():null;d.entries[id]=entry;save();sendOrQueue('complete',{task_id:id,local_date:selected,done:entry.done});render();if(entry.done&&d.tasks.find(t=>t.id===id)?.kind==='main'&&!entry.minutes)minutes(id,true)}if(el.id==='importFile'&&el.files[0]){let file=el.files[0];if(file.size>5000000)return toast('Arquivo muito grande.');file.text().then(text=>{try{let s=JSON.parse(text);if(s.version!==1||!Array.isArray(s.revisions)||!s.revisions.length||!s.days||!Array.isArray(s.courses)||s.courses.filter(c=>c.principal).length!==1)throw Error();for(let d of Object.values(s.days)){if(!Array.isArray(d.tasks)||!d.entries)throw Error()}openDialog('<h2>Restaurar sua cópia?</h2><p>Os registros atuais deste aparelho serão substituídos pelos do arquivo. Exporte uma cópia antes de continuar.</p><div class="actions">'+button('cancel','Cancelar')+'<button class="btn primary" id="restore">Restaurar</button></div>');$('#restore').onclick=()=>{state=s;save();$('#dialog').close();render();toast('Cópia restaurada.')}}catch{toast('Arquivo inválido. Escolha uma cópia exportada pelo aplicativo.')}})}});
window.addEventListener('online',flushPending);window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=JSON.parse(e.newValue);render()}catch{}}});document.addEventListener('visibilitychange',()=>{if(!document.hidden){flushPending();render()}});view=location.hash.slice(1)||'agenda';if(storageOK){ensure(state,localDate());save()}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{console.info('Modo offline indisponível neste navegador.')});
